    internal static int GetCount()
    {
        return names.Length;
    }

    internal static int GetLegacySemicolonlessCount()
    {
        return 106;
    }

    internal static int GetTwoCodePointCount()
    {
        return 93;
    }

    internal static string GetName(int index)
    {
        ValidateIndex(index);
        return names[index];
    }

    internal static int GetFirstCodePoint(int index)
    {
        ValidateIndex(index);
        return firstCodePoints[index];
    }

    internal static int GetSecondCodePoint(int index)
    {
        ValidateIndex(index);
        return secondCodePoints[index];
    }

    internal static string GetPreferredName(int firstCodePoint, int secondCodePoint)
    {
        int minimum = 0;
        int maximum = preferredNames.Length - 1;
        while (minimum <= maximum)
        {
            int middle = minimum + (maximum - minimum) / 2;
            int storedFirst = preferredFirstCodePoints[middle];
            int storedSecond = preferredSecondCodePoints[middle];
            if (firstCodePoint == storedFirst && secondCodePoint == storedSecond)
            {
                return preferredNames[middle];
            }

            if (firstCodePoint < storedFirst || firstCodePoint == storedFirst && secondCodePoint < storedSecond)
            {
                maximum = middle - 1;
            }
            else
            {
                minimum = middle + 1;
            }
        }

        return "";
    }

    internal static HtmlNamedCharacterReferenceMatch FindLongest(string input)
    {
        if (input == null)
        {
            throw new ArgumentNullException("input");
        }

        return FindLongest(input.AsSpan());
    }

    internal static HtmlNamedCharacterReferenceMatch FindLongest(ReadOnlySpan<char> input)
    {
        int nodeIndex = 0;
        int position = 0;
        int matchedValue = -1;
        int matchedLength = 0;
        while (position < input.Length)
        {
            int edgeIndex = FindEdge(nodeIndex, input[position]);
            if (edgeIndex < 0)
            {
                break;
            }

            nodeIndex = edgeTargets[edgeIndex];
            position = position + 1;
            int valueIndex = nodeValues[nodeIndex];
            if (valueIndex >= 0)
            {
                matchedValue = valueIndex;
                matchedLength = position;
            }
        }

        if (matchedValue < 0)
        {
            return new HtmlNamedCharacterReferenceMatch(false, 0, -1, -1, false);
        }

        bool hasSemicolon = input[matchedLength - 1] == ';';
        return new HtmlNamedCharacterReferenceMatch(true, matchedLength,
            firstCodePoints[matchedValue], secondCodePoints[matchedValue], hasSemicolon);
    }

    internal static int FindEdge(int nodeIndex, char value)
    {
        int minimum = nodeFirstEdges[nodeIndex];
        int maximum = minimum + nodeEdgeCounts[nodeIndex] - 1;
        while (minimum <= maximum)
        {
            int middle = minimum + (maximum - minimum) / 2;
            char edge = edgeCharacters[middle];
            if (value == edge)
            {
                return middle;
            }

            if (value < edge)
            {
                maximum = middle - 1;
            }
            else
            {
                minimum = middle + 1;
            }
        }

        return -1;
    }

    internal static void ValidateIndex(int index)
    {
        if (index < 0 || index >= names.Length)
        {
            throw new ArgumentOutOfRangeException("index", index, "The named character reference index is outside the table.");
        }
    }
